  1	package com.loja.database;
  2	
  3	import com.zaxxer.hikari.HikariConfig;
  4	import com.zaxxer.hikari.HikariDataSource;
  5	import com.loja.models.*;
  6	
  7	import java.sql.*;
  8	import java.util.*;
  9	
 10	public class Database {
 11	    private static HikariDataSource dataSource;
 12	
 13	    public static void init(String dbUrl, String dbUser, String dbPassword) throws SQLException {
 14	        HikariConfig config = new HikariConfig();
 15	        config.setJdbcUrl(dbUrl);
 16	        config.setUsername(dbUser);
 17	        config.setPassword(dbPassword);
 18	        config.setMaximumPoolSize(10);
 19	        dataSource = new HikariDataSource(config);
 20	
 21	        migrate();
 22	    }
 23	
 24	    private static void migrate() throws SQLException {
 25	        try (Connection conn = dataSource.getConnection()) {
 26	            Statement stmt = conn.createStatement();
 27	
 28	            stmt.execute("""
 29	                CREATE TABLE IF NOT EXISTS products (
 30	                    sku VARCHAR(20) PRIMARY KEY,
 31	                    name VARCHAR(255) NOT NULL,
 32	                    price DECIMAL(10, 2) NOT NULL,
 33	                    weight_kg DECIMAL(5, 2) NOT NULL,
 34	                    stock INT NOT NULL,
 35	                    discontinued BOOLEAN NOT NULL DEFAULT FALSE
 36	                )
 37	                """);
 38	
 39	            stmt.execute("""
 40	                CREATE TABLE IF NOT EXISTS customers (
 41	                    cpf VARCHAR(11) PRIMARY KEY,
 42	                    email VARCHAR(255) NOT NULL,
 43	                    credit_balance DECIMAL(10, 2) NOT NULL DEFAULT 0.00
 44	                )
 45	                """);
 46	
 47	            stmt.execute("""
 48	                CREATE TABLE IF NOT EXISTS orders (
 49	                    id VARCHAR(36) PRIMARY KEY,
 50	                    cpf VARCHAR(11) NOT NULL REFERENCES customers(cpf),
 51	                    email VARCHAR(255) NOT NULL,
 52	                    status VARCHAR(30) NOT NULL,
 53	                    created_at TIMESTAMP NOT NULL,
 54	                    products_subtotal DECIMAL(10, 2) NOT NULL,
 55	                    coupon_discount DECIMAL(10, 2) NOT NULL,
 56	                    shipping_cost DECIMAL(10, 2) NOT NULL,
 57	                    delivery_days INT NOT NULL,
 58	                    insurance DECIMAL(10, 2) NOT NULL,
 59	                    payment_adjustment DECIMAL(10, 2) NOT NULL,
 60	                    final_total DECIMAL(10, 2) NOT NULL,
 61	                    installments INT NOT NULL,
 62	                    installment_amount DECIMAL(10, 2) NOT NULL,
 63	                    next_purchase_credit DECIMAL(10, 2) NOT NULL,
 64	                    gift BOOLEAN NOT NULL,
 65	                    tracking_code VARCHAR(50),
 66	                    region VARCHAR(20) NOT NULL,
 67	                    shipping_method VARCHAR(20) NOT NULL,
 68	                    payment_method VARCHAR(20) NOT NULL,
 69	                    club_tier VARCHAR(10) NOT NULL,
 70	                    coupon VARCHAR(50),
 71	                    paid_at TIMESTAMP,
 72	                    payment_transaction_id VARCHAR(100)
 73	                )
 74	                """);
 75	
 76	            stmt.execute("""
 77	                CREATE TABLE IF NOT EXISTS order_items (
 78	                    id SERIAL PRIMARY KEY,
 79	                    order_id VARCHAR(36) NOT NULL REFERENCES orders(id),
 80	                    sku VARCHAR(20) NOT NULL REFERENCES products(sku),
 81	                    quantity INT NOT NULL
 82	                )
 83	                """);
 84	
 85	            stmt.execute("""
 86	                CREATE TABLE IF NOT EXISTS notifications (
 87	                    id VARCHAR(36) PRIMARY KEY,
 88	                    cpf VARCHAR(11) NOT NULL REFERENCES customers(cpf),
 89	                    type VARCHAR(30) NOT NULL,
 90	                    order_id VARCHAR(36),
 91	                    status VARCHAR(10) NOT NULL,
 92	                    created_at TIMESTAMP NOT NULL
 93	                )
 94	                """);
 95	
 96	            stmt.close();
 97	        }
 98	
 99	        loadInitialCatalog();
100	    }
101	
102	    private static void loadInitialCatalog() throws SQLException {
103	        try (Connection conn = dataSource.getConnection()) {
104	            PreparedStatement pstmt = conn.prepareStatement(
105	                "SELECT COUNT(*) FROM products");
106	            ResultSet rs = pstmt.executeQuery();
107	            rs.next();
108	            if (rs.getInt(1) == 0) {
109	                insertProduct(conn, "CAM-001", "Camiseta básica", 79.90, 0.30, 50, false);
110	                insertProduct(conn, "TEN-001", "Tênis corrida", 249.90, 1.20, 10, false);
111	                insertProduct(conn, "FON-001", "Fone sem fio", 199.90, 0.25, 5, false);
112	                insertProduct(conn, "MEI-001", "Meia esportiva", 19.90, 0.10, 100, false);
113	                insertProduct(conn, "JAQ-001", "Jaqueta corta-vento", 389.90, 0.80, 3, false);
114	                insertProduct(conn, "MOC-001", "Mochila urbana", 159.90, 0.90, 1, false);
115	                insertProduct(conn, "BON-001", "Boné aba reta", 59.90, 0.15, 0, false);
116	                insertProduct(conn, "REL-001", "Relógio digital", 129.90, 0.20, 8, true);
117	                conn.commit();
118	            }
119	            rs.close();
120	            pstmt.close();
121	        }
122	    }
123	
124	    private static void insertProduct(Connection conn, String sku, String name, double price,
125	                                     double weightKg, int stock, boolean discontinued) throws SQLException {
126	        String sql = "INSERT INTO products (sku, name, price, weight_kg, stock, discontinued) VALUES (?, ?, ?, ?, ?, ?)";
127	        PreparedStatement pstmt = conn.prepareStatement(sql);
128	        pstmt.setString(1, sku);
129	        pstmt.setString(2, name);
130	        pstmt.setDouble(3, price);
131	        pstmt.setDouble(4, weightKg);
132	        pstmt.setInt(5, stock);
133	        pstmt.setBoolean(6, discontinued);
134	        pstmt.executeUpdate();
135	        pstmt.close();
136	    }
137	
138	    public static HikariDataSource getDataSource() {
139	        return dataSource;
140	    }
141	
142	    public static void close() {
143	        if (dataSource != null) {
144	            dataSource.close();
145	        }
146	    }
147	}
  1	package com.loja;
