  3	import com.loja.api.Routes;
  4	import com.loja.database.Database;
  5	import io.javalin.Javalin;
  6	import io.javalin.json.JsonMapper;
  7	
  8	import java.lang.reflect.Type;
  9	
 10	public class App {
 11	    public static void main(String[] args) throws Exception {
 12	        String dbUrl = System.getenv("DB_URL");
 13	        String dbUser = System.getenv("DB_USER");
 14	        String dbPassword = System.getenv("DB_PASSWORD");
 15	        String port = System.getenv("PORT");
 16	
 17	        if (dbUrl == null || dbUrl.isEmpty()) {
 18	            dbUrl = "jdbc:postgresql://localhost:5432/orderservice";
 19	        }
 20	        if (dbUser == null || dbUser.isEmpty()) {
 21	            dbUser = "postgres";
 22	        }
 23	        if (dbPassword == null || dbPassword.isEmpty()) {
 24	            dbPassword = "postgres";
 25	        }
 26	        if (port == null || port.isEmpty()) {
 27	            port = "8080";
 28	        }
 29	
 30	        Database.init(dbUrl, dbUser, dbPassword);
 31	
 32	        int portNum = Integer.parseInt(port);
 33	
 34	        Javalin app = Javalin.create(config -> {
 35	            config.jsonMapper(new JsonMapper() {
 36	                private final com.google.gson.Gson gson = new com.google.gson.Gson();
 37	
 38	                @Override
 39	                public String toJsonString(Object obj, Type type) {
 40	                    return gson.toJson(obj, type);
 41	                }
 42	
 43	                @Override
 44	                public Object fromJsonString(String json, Type targetType) {
 45	                    return gson.fromJson(json, targetType);
 46	                }
 47	            });
 48	        }).start(portNum);
 49	
 50	        Routes.setup(app);
 51	
 52	        System.out.println("Order service started on port " + portNum);
 53	    }
 54	}

