 10	
 11	public class PaymentService {
 12	    private static final long PAYMENT_TIMEOUT_MS = 48 * 60 * 60 * 1000;
 13	
 14	    public static class PaymentResult {
 15	        public String error;
 16	        public int httpStatus;
 17	        public Order order;
 18	        public boolean success;
 19	
 20	        public PaymentResult(String error, int httpStatus) {
 21	            this.error = error;
 22	            this.httpStatus = httpStatus;
 23	            this.success = false;
 24	        }
 25	
 26	        public PaymentResult(Order order) {
 27	            this.order = order;
 28	            this.success = true;
 29	        }
 30	    }
 31	
 32	    public static PaymentResult processPayment(String orderId, PaymentRequest paymentReq) throws SQLException {
 33	        Order order = OrderService.getOrder(orderId);
 34	        if (order == null) {
 35	            return new PaymentResult("ORDER_NOT_FOUND", 404);
 36	        }
 37	
 38	        if (paymentReq.transactionId == null || paymentReq.transactionId.isEmpty() ||
 39	            paymentReq.paidAt == null || paymentReq.paidAt.isEmpty()) {
 40	            return new PaymentResult("INVALID_ORDER", 422);
 41	        }
 42	
 43	        if (order.status != Enums.OrderStatus.AWAITING_PAYMENT) {
 44	            if (OrderService.isPaymentDuplicate(orderId, paymentReq.transactionId)) {
 45	                return new PaymentResult(order);
 46	            }
 47	            return new PaymentResult("OPERATION_NOT_ALLOWED", 409);
 48	        }
 49	
 50	        Instant paidAt = Instant.parse(paymentReq.paidAt);
 51	        Instant createdAt = order.createdAt;
 52	        long timeDiffMs = paidAt.toEpochMilli() - createdAt.toEpochMilli();
 53	
 54	        if (timeDiffMs > PAYMENT_TIMEOUT_MS) {
 55	            OrderService.updateOrderStatus(orderId, Enums.OrderStatus.CANCELLED);
 56	            String cpf = OrderService.getCustomerCpf(orderId);
 57	            NotificationService.createNotification(cpf, Enums.NotificationType.ORDER_CANCELLED, orderId);
 58	            return new PaymentResult("ORDER_EXPIRED", 409);
 59	        }
 60	
 61	        for (OrderItem item : order.items) {
 62	            if (ProductService.getProduct(item.sku).stock < item.quantity) {
 63	                OrderService.updateOrderStatus(orderId, Enums.OrderStatus.CANCELLED);
 64	                String cpf = OrderService.getCustomerCpf(orderId);
 65	                NotificationService.createNotification(cpf, Enums.NotificationType.ORDER_CANCELLED, orderId);
 66	                return new PaymentResult("INSUFFICIENT_STOCK", 409);
 67	            }
 68	        }
 69	
 70	        for (OrderItem item : order.items) {
 71	            ProductService.updateStock(item.sku, -item.quantity);
 72	        }
 73	
 74	        String cpf = OrderService.getCustomerCpf(orderId);
 75	        CustomerService.updateCreditBalance(cpf, order.summary.nextPurchaseCredit);
 76	
 77	        OrderService.recordPayment(orderId, paymentReq.transactionId, paidAt);
 78	        OrderService.updateOrderStatus(orderId, Enums.OrderStatus.PAID);
 79	
 80	        NotificationService.createNotification(cpf, Enums.NotificationType.PAYMENT_APPROVED, orderId);
 81	
 82	        return new PaymentResult(OrderService.getOrder(orderId));
 83	    }
 84	}
